use super::*;
use crate::money::money;

/// The scenario table: what happens across a ladder of moves, and which ones you never reach.
///
/// The unreachable rows are KEPT rather than filtered, because seeing that +30% is past your call
/// price is the entire point — a table that stopped at the call would hide how ordinary a move it is.
pub fn ladder(cap: &Capacity, shares: i64, moves: &[f64], carry: &Carry) -> Vec<Outcome> {
    moves
        .iter()
        .map(|m| outcome_at(cap, shares, money(((cap.price.minor as f64) * (1.0 + m)).round() as i64, cap.equity.currency), carry))
        .collect()
}
